from __future__ import (absolute_import, division, print_function)
__metaclass__ = type

import errno
import re
import time


def get_sysctl(module, prefixes):
    try:
        sysctl_cmd = module.get_bin_path('sysctl')
        if not sysctl_cmd:
            raise OSError('sysctl binary not found')
        rc, out, err = module.run_command([sysctl_cmd] + prefixes)
    except (IOError, OSError) as e:
        module.warn('Unable to read sysctl: %s' % e)
        return {}
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % ((err or '').strip() or 'exit code %s' % rc))
        return {}

    sysctl = {}
    previous_key = None
    for line in out.splitlines():
        if not line and previous_key is None:
            continue
        if not line or line[0].isspace():
            if previous_key is None:
                module.warn('Unable to split sysctl line (%s): no preceding key' % line)
            else:
                sysctl[previous_key] += '\n' + line
            continue
        try:
            match = re.match(r'^([^\s=:]+)(?:\s*=\s*|\s*:\s*|\s+)(.*)$', line)
            if match is None:
                raise ValueError('not enough values to unpack (expected 2, got 1)')
            key, value = match.groups()
        except ValueError as e:
            module.warn('Unable to split sysctl line (%s): %s' % (line, e))
            previous_key = None
            continue
        sysctl[key] = value.strip()
        previous_key = key

    return sysctl


def get_uptime_facts(module):
    try:
        sysctl_cmd = module.get_bin_path('sysctl')
        if not sysctl_cmd:
            raise ValueError('sysctl binary not found')
        rc, out, err = module.run_command([sysctl_cmd, '-n', 'kern.boottime'])
    except (IOError, OSError) as e:
        if e.errno == errno.ENOENT:
            raise ValueError('sysctl binary not found')
        module.warn('Unable to read sysctl: %s' % e)
        return {}

    if rc != 0:
        return {}
    boottime = out.strip()
    if not re.match(r'^[0-9]+$', boottime):
        return {}
    return {'uptime_seconds': int(time.time() - int(boottime))}
